mod solution;

fn main() {
    let cases = [
    (r#"[4,1,9,7,3,8]"#, r#"9,8,7"#),
    (r#"[1,2,3,4]"#, r#"4,3,2"#),
    (r#"
[1,2,3,4]
"#, r#"4,3,2"#),
    (r#"  
[4,1,9,7,3,8]
  "#, r#"9,8,7"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS top-k-minheap");
}
